"""Derived items: entity pages and narratives (L0/L1), regenerated by watermark."""

from __future__ import annotations

import numpy as np

from .. import events
from .. import knowledge as K
from ..ids import new_id, sha
from ..llm.client import CallContext
from ..services import Services
from . import prompts, schemas
from .process import integrate

NARRATIVE_VERSION = f"narrative-{prompts.VERSION}"


def _save_view(conn, svc: Services, *, view_id: str | None, kind: str, entity_id: str | None, title: str,
               l0: str, l1: str, cited: list[str], members: list[str], watermark: str, vec, status: str = "active") -> str:
    model = svc.settings.model_for("synthesis")
    if view_id:
        row = conn.execute(
            """UPDATE views SET title = %s, l0 = %s, l1 = %s, cited_claim_ids = %s, member_entity_ids = %s,
                      watermark = %s, stale = false, status = %s, version = version + 1, model = %s,
                      generated_at = now(), embedding = %s
               WHERE id = %s RETURNING id, version, generated_at""",
            (title, l0, l1, cited, members, watermark, status, model, vec, view_id)).fetchone()
    else:
        view_id = new_id("vw")
        row = conn.execute(
            """INSERT INTO views (id, kind, entity_id, title, l0, l1, cited_claim_ids, member_entity_ids, watermark,
                                  status, model, generated_at, embedding)
               VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, now(), %s) RETURNING id, version, generated_at""",
            (view_id, kind, entity_id, title, l0, l1, cited, members, watermark, status, model, vec)).fetchone()
    conn.execute(
        """INSERT INTO view_versions (view_id, version, title, l0, l1, cited_claim_ids, member_entity_ids, status,
                                      generated_at, cause)
           VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)""",
        (row["id"], row["version"], title, l0, l1, cited, members, status, row["generated_at"], events.CAUSE.get()))
    return row["id"]


def entity_synthesis_input(conn, svc: Services, entity_id: str) -> dict | None:
    """Assembles an entity's synthesis, or None when there is nothing to regenerate (same watermark,
    inactive entity or no current claims). Used by online synthesis and batch synthesis."""
    ent = K.entity(conn, entity_id)
    if not ent or ent["status"] != "active":
        return None
    watermark = K.entity_watermark(conn, entity_id)
    view = conn.execute("SELECT * FROM views WHERE kind = 'entity' AND entity_id = %s", (entity_id,)).fetchone()
    if view and view["watermark"] == watermark and view["status"] == "active":
        conn.execute("UPDATE views SET stale = false WHERE id = %s", (view["id"],))
        return None
    current = K.entity_claims(conn, entity_id, limit=150)
    past = K.entity_claims(conn, entity_id, ("superseded",), limit=20)
    if not current:
        if view:
            conn.execute("UPDATE views SET status = 'retired', stale = false, watermark = %s WHERE id = %s",
                         (watermark, view["id"]))
        return None
    lines = [f"Entity {ent['id']}: {ent['name']} ({ent['type']})"]
    if ent["aliases"]:
        lines.append("Aliases: " + ", ".join(ent["aliases"]))
    if ent["is_owner"]:
        lines.append("This entity is the owner of Pythia.")
    lines.append("\nCurrent claims:")
    lines.extend("- " + K.format_claim(c) for c in current)
    if past:
        lines.append("\nSuperseded claims (history):")
        lines.extend("- " + K.format_claim(c) for c in past)
    return {"system": prompts.SYNTH_ENTITY.format(owner=svc.owner_name), "user": "\n".join(lines),
            "schema": schemas.SYNTH_ENTITY, "watermark": watermark, "source_id": current[0]["source_id"]}


def apply_entity_synthesis(svc: Services, entity_id: str, out: dict, watermark: str, *,
                           narratives_delay_s: float | None = 60) -> str | None:
    """Records the page. If the claims changed after the request was assembled (e.g. the batch took long and
    day-to-day work touched the entity), the page is recorded and an online regeneration is scheduled."""
    with svc.db.tx() as conn:
        ent = K.entity(conn, entity_id)
        if not ent or ent["status"] != "active":
            return None
        allowed = {r["id"] for r in conn.execute(
            "SELECT id FROM claims WHERE subject_entity_id = %s OR object_entity_id = %s",
            (entity_id, entity_id)).fetchall()}
        view = conn.execute("SELECT id FROM views WHERE kind = 'entity' AND entity_id = %s", (entity_id,)).fetchone()
    cited = sorted({c for c in out["cited_claim_ids"] if c in allowed})
    vec = np.array(svc.embedder.embed([f"{ent['name']}: {out['l0']}"])[0], dtype=np.float32)
    from ..jobs import enqueue
    with svc.db.tx() as conn:
        vid = _save_view(conn, svc, view_id=view["id"] if view else None, kind="entity", entity_id=entity_id,
                         title=ent["name"], l0=out["l0"], l1=out["l1"], cited=cited, members=[entity_id],
                         watermark=watermark, vec=vec)
        conn.execute("UPDATE entities SET embedding = %s WHERE id = %s", (vec, entity_id))
        # Narratives that depend on this entity need to be reviewed.
        conn.execute("UPDATE views SET stale = true WHERE kind = 'narrative' AND status = 'active' AND %s = ANY(member_entity_ids)",
                     (entity_id,))
        if K.entity_watermark(conn, entity_id) != watermark:
            enqueue(conn, "derive_entity", "derivation", {"entity_id": entity_id}, priority=60,
                    dedup_key=f"derive:{entity_id}", delay_s=K.DERIVE_DELAY_S)
        if narratives_delay_s is not None:
            enqueue(conn, "derive_narratives", "derivation", {}, priority=80, dedup_key="narratives",
                    delay_s=narratives_delay_s)
    return vid


def derive_entity(svc: Services, entity_id: str, job_id: int | None = None) -> dict:
    with svc.db.tx() as conn:
        # Entity waiting for a backfill's single pass: any path that schedules it
        # online (sweep, cascade outside the backfill context) is ignored here.
        if conn.execute("SELECT 1 FROM deferred_derivations WHERE entity_id = %s", (entity_id,)).fetchone():
            return {"skipped": "synthesis deferred by the backfill"}
        # Already in a synthesis batch in progress: the result arrives through there; changes after that are
        # picked up by the sweep when the batch ends.
        if conn.execute("""SELECT 1 FROM batch_requests WHERE entity_id = %s AND kind = 'synthesis'
                           AND status IN ('pending', 'submitted')""", (entity_id,)).fetchone():
            return {"skipped": "batch synthesis in progress"}
        prepared = entity_synthesis_input(conn, svc, entity_id)
    if prepared is None:
        return {"skipped": "nothing to regenerate"}
    out = svc.llm.structured("synthesis", prepared["system"], prepared["user"], prepared["schema"],
                             ctx=CallContext(source_id=prepared["source_id"], job_id=job_id))
    return {"view_id": apply_entity_synthesis(svc, entity_id, out, prepared["watermark"])}


def knowledge_map(conn, limit: int = 400) -> str:
    """L0 map: narratives first, then pages. Deterministic assembly (no judgment)."""
    rows = conn.execute(
        """SELECT id, kind, title, l0 FROM views WHERE status = 'active'
           ORDER BY (kind = 'narrative') DESC, generated_at DESC LIMIT %s""", (limit,)).fetchall()
    return "\n".join(f"{r['id']} · [{r['kind']}] {r['title']} — {r['l0']}" for r in rows)


def retire_unsupported_narratives(conn) -> int:
    """Cascade, as for the entity page: a narrative with no cited claim still current has nothing
    to support its text and goes away (the content may have been erased at the source)."""
    rows = conn.execute(
        """SELECT * FROM views v WHERE v.kind = 'narrative' AND v.status = 'active'
             AND NOT EXISTS (SELECT 1 FROM claims c WHERE c.id = ANY(v.cited_claim_ids)
                             AND c.status IN ('current', 'disputed'))""").fetchall()
    for v in rows:
        row = conn.execute(
            """UPDATE views SET status = 'retired', stale = false, version = version + 1, generated_at = now()
               WHERE id = %s RETURNING version, generated_at""", (v["id"],)).fetchone()
        conn.execute(
            """INSERT INTO view_versions (view_id, version, title, l0, l1, cited_claim_ids, member_entity_ids, status, generated_at)
               VALUES (%s, %s, %s, %s, %s, %s, %s, 'retired', %s)""",
            (v["id"], row["version"], v["title"], v["l0"], v["l1"], v["cited_claim_ids"], v["member_entity_ids"],
             row["generated_at"]))
    return len(rows)


def derive_narratives(svc: Services, job_id: int | None = None, review: bool = False) -> dict:
    """`review`: full pass even without changes (consolidate overlapping narratives)."""
    with svc.db.tx() as conn:
        retired = retire_unsupported_narratives(conn)
        narratives = conn.execute(
            "SELECT * FROM views WHERE kind = 'narrative' AND status = 'active' ORDER BY generated_at").fetchall()
        last = conn.execute("SELECT value FROM system_state WHERE key = 'narratives_pass'").fetchone()
        since = last["value"]["at"] if last else "1970-01-01"
        pages = conn.execute(
            """SELECT id, entity_id, title, l0, generated_at > %s::timestamptz AS changed FROM views
               WHERE kind = 'entity' AND status = 'active' ORDER BY generated_at DESC LIMIT 300""",
            (since,)).fetchall()
        stale = [n for n in narratives if n["stale"]]
        changed = [p for p in pages if p["changed"]]
        if not stale and not changed and not review:
            return {"skipped": "nothing changed", "retired_unsupported": retired}
        recent = conn.execute(
            """SELECT c.*, s.name AS subject_name FROM claims c LEFT JOIN entities s ON s.id = c.subject_entity_id
               WHERE c.status IN ('current', 'disputed') AND c.recorded_at > %s::timestamptz
               ORDER BY c.recorded_at DESC LIMIT 120""", (since,)).fetchall()
        # Incremental input: only the affected (stale) narratives go in full, with their claims; the
        # others go with the summary only. In the review pass, all go in full.
        full = {n["id"] for n in narratives if review or n["stale"]}
        if not review:
            pages = [p for p in pages if p["changed"]]
        cited_ids = sorted({cid for n in narratives if n["id"] in full for cid in n["cited_claim_ids"]})
        cited = conn.execute(
            """SELECT c.*, s.name AS subject_name FROM claims c LEFT JOIN entities s ON s.id = c.subject_entity_id
               WHERE c.id = ANY(%s)""", (cited_ids,)).fetchall()
        now = conn.execute("SELECT now() AS t").fetchone()["t"]
    status_of = {c["id"]: c for c in cited}
    lines = ["EXISTING NARRATIVES (the affected ones, in full, with the claims each one cites)"]
    for n in narratives:
        if n["id"] not in full:
            continue
        flag = " (STALE)" if n["stale"] else ""
        changed_claims = [cid for cid in n["cited_claim_ids"] if status_of.get(cid, {}).get("status") not in ("current", "disputed")]
        lines.append(f"- {n['id']}{flag} · {n['title']} — {n['l0']}\n  members: {', '.join(n['member_entity_ids'])}"
                     + (f"\n  cited claims whose status changed: {', '.join(changed_claims)}" if changed_claims else ""))
        lines.extend(f"    · [{status_of[cid]['subject_name']}] " + K.format_claim(status_of[cid])
                     for cid in n["cited_claim_ids"]
                     if status_of.get(cid, {}).get("status") in ("current", "disputed"))
    if not narratives:
        lines.append("(none)")
    summarized = [n for n in narratives if n["id"] not in full]
    if summarized:
        lines.append("\nUNAFFECTED NARRATIVES (summary only; the claims and text were not shown)")
        lines.extend(f"- {n['id']} · {n['title']} — {n['l0']}\n  members: {', '.join(n['member_entity_ids'])}"
                     for n in summarized)
    lines.append("\nENTITY PAGES (L0; * = changed since the last pass)" if review else
                 "\nENTITY PAGES THAT CHANGED SINCE THE LAST PASS (L0)")
    lines.extend(f"- {'*' if p['changed'] else ' '} {p['entity_id']} · {p['title']} — {p['l0']}" for p in pages)
    lines.append("\nRECENT CLAIMS")
    lines.extend(f"- [{c['subject_name']}] " + K.format_claim(c) for c in recent)
    out = svc.llm.structured("synthesis", prompts.SYNTH_NARRATIVES.format(owner=svc.owner_name), "\n".join(lines),
                             schemas.SYNTH_NARRATIVES, ctx=CallContext(job_id=job_id))
    known_views = {n["id"]: n for n in narratives}
    with svc.db.tx() as conn:
        valid_entities = {r["id"] for r in conn.execute("SELECT id FROM entities WHERE status = 'active'").fetchall()}
        texts = [f"{n['title']}: {n['l0']}" for n in out["narratives"]]
    vecs = svc.embedder.embed(texts) if texts else []
    applied = 0
    deferred: list[str] = []
    with svc.db.tx() as conn:
        for n, v in zip(out["narratives"], vecs):
            if n["op"] != "create" and n["id"] in known_views and n["id"] not in full:
                # Changing a narrative that went in with the summary only would lose text and citations the LLM did not see:
                # it comes back in full on the next pass, which runs soon.
                deferred.append(n["id"])
                continue
            members = [e for e in n["member_entity_ids"] if e in valid_entities]
            cited_valid = [r["id"] for r in conn.execute("SELECT id FROM claims WHERE id = ANY(%s)",
                                                         (n["cited_claim_ids"],)).fetchall()]
            watermark = sha("|".join(sorted(cited_valid)))
            vec = np.array(v, dtype=np.float32)
            if n["op"] == "create" or (n["op"] == "update" and n["id"] not in known_views):
                _save_view(conn, svc, view_id=None, kind="narrative", entity_id=None, title=n["title"], l0=n["l0"],
                           l1=n["l1"], cited=cited_valid, members=members, watermark=watermark, vec=vec)
            elif n["op"] == "update":
                _save_view(conn, svc, view_id=n["id"], kind="narrative", entity_id=None, title=n["title"], l0=n["l0"],
                           l1=n["l1"], cited=cited_valid, members=members, watermark=watermark, vec=vec)
            elif n["op"] == "retire" and n["id"] in known_views:
                old = known_views[n["id"]]
                _save_view(conn, svc, view_id=old["id"], kind="narrative", entity_id=None, title=old["title"],
                           l0=old["l0"], l1=old["l1"], cited=old["cited_claim_ids"], members=old["member_entity_ids"],
                           watermark=old["watermark"], vec=vec, status="retired")
            applied += 1
        conn.execute("UPDATE views SET stale = false WHERE kind = 'narrative' AND status = 'active'")
        if deferred:
            # The next pass shows these in full and the same recent claims (the mark does not advance).
            conn.execute("UPDATE views SET stale = true WHERE id = ANY(%s)", (deferred,))
            from ..jobs import enqueue
            enqueue(conn, "derive_narratives", "derivation", {}, priority=80, dedup_key="narratives", delay_s=60)
            conn.execute("""UPDATE jobs SET run_after = least(run_after, now() + interval '60 seconds')
                            WHERE dedup_key = 'narratives' AND status = 'queued'""")
        else:
            conn.execute(
                """INSERT INTO system_state (key, value) VALUES ('narratives_pass', jsonb_build_object('at', %s::text))
                   ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now()""", (now.isoformat(),))
    # Inferences become `inferred` claims and go through the same integration as the others.
    inferred = []
    with svc.db.tx() as conn:
        for inf in out["inferences"]:
            if inf["subject_entity_id"] not in valid_entities:
                continue
            support = [r["id"] for r in conn.execute("SELECT id FROM claims WHERE id = ANY(%s)",
                                                     (inf["supporting_claim_ids"],)).fetchall()]
            if not support:
                continue
            inferred.append({
                "ref": f"N{len(inferred) + 1}", "kind": inf["kind"], "subject_mention_id": None,
                "subject_entity_id": inf["subject_entity_id"], "predicate": inf["predicate"],
                "object_value": inf["value"], "object_mention_id": None, "object_entity_id": None,
                "statement": inf["statement"], "valid_from": None, "valid_to": None, "origin": "inferred",
                "source_id": None, "source_label": f"llm:{NARRATIVE_VERSION}", "confidence": 0.6,
                "extractor_version": NARRATIVE_VERSION, "evidence_ids": [], "supporting_claim_ids": support,
            })
    if inferred:
        from ..jobs import enqueue
        with svc.db.tx() as conn:
            enqueue(conn, "integrate_inferences", "cognition", {"candidates": inferred}, priority=70)
    return {"narratives": applied, "inferences": len(inferred), "retired_unsupported": retired,
            "deferred": len(deferred), "full": len(full), "summarized": len(narratives) - len(full)}


def integrate_inferences(svc: Services, candidates: list[dict], job_id: int | None = None) -> dict:
    asserted = integrate(svc, candidates, CallContext(job_id=job_id), actor="synthesis")
    return {"claims": len(asserted)}


def sweep(svc: Services) -> int:
    """Schedules regeneration of entities with claims changed after the page (or with no page)."""
    from ..jobs import enqueue
    with svc.db.tx() as conn:
        rows = conn.execute(
            """SELECT DISTINCT e.id FROM entities e
               JOIN claims c ON (c.subject_entity_id = e.id OR c.object_entity_id = e.id)
               LEFT JOIN views v ON v.kind = 'entity' AND v.entity_id = e.id
               WHERE e.status = 'active'
                 AND NOT EXISTS (SELECT 1 FROM deferred_derivations d WHERE d.entity_id = e.id)
                 AND NOT EXISTS (SELECT 1 FROM batch_requests b WHERE b.entity_id = e.id AND b.kind = 'synthesis'
                                 AND b.status IN ('pending', 'submitted'))
                 AND (v.id IS NULL OR v.stale OR c.recorded_at > v.generated_at
                     OR EXISTS (SELECT 1 FROM claim_status_history h WHERE h.claim_id = c.id AND h.from_ts > v.generated_at))
               LIMIT 200""").fetchall()
        for r in rows:
            enqueue(conn, "derive_entity", "derivation", {"entity_id": r["id"]}, priority=90, dedup_key=f"derive:{r['id']}")
    return len(rows)


def integrate_structured(svc: Services, candidates: list[dict], job_id: int | None = None) -> dict:
    """Claims coming from structured records (catalog): no extraction, but with LLM integration.
    During the source's first load, regeneration of derived items is deferred as in every backfill."""
    from .batch import source_in_backfill

    source_id = candidates[0].get("source_id") if candidates else None
    with svc.db.tx() as conn:
        in_backfill = source_in_backfill(conn, source_id)
    token = K.DEFER.set(source_id) if in_backfill else None
    try:
        asserted = integrate(svc, candidates, CallContext(source_id=source_id, job_id=job_id), actor="integration")
    finally:
        if token is not None:
            K.DEFER.reset(token)
    return {"claims": len(asserted)}
